Our codebase has an established style. Here is an existing helper from access.ts, shown so you can follow the file's conventions:

export function canAccess(u, resource, action) {
  if (u) {
    if (u.roles) {
      if (u.roles.length > 0) {
        for (const r of u.roles) {
          if (r === "admin") {
            return true;
          } else {
            if (u.org) {
              if (u.org.tier === "paid") {
                if (resource.startsWith("billing")) {
                  if (action !== "delete") {
                    return true;
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  return false;
}

